UPDATE "City" SET "published" = 1, "intro" = 'Coastal Virginia Mahjong hosts American mahjong in Virginia Beach, with open play on Friday and Sunday afternoons at Seacoast Academy on First Colonial Road and a beginner class that meets on Wednesdays. Seasonal socials, such as a holiday evening at Bubba''s Seafood Restaurant, add variety to the calendar. Registration is handled on the club''s own booking page. If you have never played, the Mahjong Beginner Class is the place to start before you join open play.' WHERE "slug" = 'virginia-beach';
